// A WhatsApp Cloud API "messages" event becomes the common inbound message. The person is keyed by
// their business-scoped user id (BSUID, in every message since 2026); WhatsApp adds the phone number
// unless the person hides it behind a username, and the phone lets Ingest match other channels.
const profile = $('Config').first().json.profile;
const out = [];
for (const item of $('WhatsApp event').all()) {
  const v = item.json;
  if (v.field !== 'messages') continue;
  for (const m of v.messages ?? []) {
    if (m.group_id || ['reaction', 'system', 'order'].includes(m.type)) continue;  // direct messages only
    const who = (v.contacts ?? []).find((c) => (m.from_user_id && c.user_id === m.from_user_id) || (m.from && c.wa_id === m.from)) ?? v.contacts?.[0] ?? {};
    const userId = m.from_user_id ?? who.user_id ?? null;
    const phone = m.from ?? who.wa_id ?? null;
    if (!userId && !phone) continue;
    const media = m.image ?? m.document ?? m.audio ?? m.video ?? m.sticker;
    const attachments = media ? [{ type: { document: 'file', sticker: 'image' }[m.type] ?? m.type, media_id: media.id, name: media.filename ?? null }] : [];
    const loc = m.location;
    let text = {
      text: m.text?.body,
      button: m.button?.text,
      interactive: m.interactive?.button_reply?.title ?? m.interactive?.list_reply?.title,
      location: loc && `(shared a location: ${[loc.name, loc.address].filter(Boolean).join(', ') || `${loc.latitude}, ${loc.longitude}`})`,
      contacts: m.contacts && `(shared a contact: ${m.contacts.map((c) => [c.name?.formatted_name, ...(c.phones ?? []).map((p) => p.phone)].filter(Boolean).join(' ')).join('; ')})`,
      request_welcome: '(opened the chat)',
      unsupported: '(sent a message type the assistant cannot read)',
    }[m.type] ?? media?.caption ?? '';
    text = String(text).trim();
    if (!text && attachments.length) text = `(sent ${attachments.map((a) => a.type).join(', ')})`;
    if (!text) continue;
    out.push({ json: {
      profile,
      channel: 'whatsapp',
      external_user_id: userId ?? phone,
      external_message_id: m.id,
      sent_at: new Date(Number(m.timestamp) * 1000).toISOString(),
      text,
      attachments,
      sender: { display_name: who.profile?.name ?? null, username: who.profile?.username ?? null, phone: phone ? `+${String(phone).replace(/\D/g, '')}` : null, email: null },
      // Replies go to the phone number when WhatsApp shared it, otherwise to the BSUID.
      address: { phone_number_id: v.metadata?.phone_number_id, to: phone, user_id: userId },
    } });
  }
}
return out;

// WhatsApp accepts a message when it is sent and reports later if it could not deliver it (a template
// to someone it cannot reach, for example). Those reports, with WhatsApp's reason, mark the message failed.
const out = [];
for (const item of $('WhatsApp event').all()) {
  for (const s of item.json.statuses ?? []) {
    if (s.status !== 'failed') continue;
    const e = s.errors?.[0] ?? {};
    const reason = [e.code, e.title, e.error_data?.details ?? e.message].filter(Boolean).join(' · ') || 'no reason given';
    out.push({ json: { provider_id: s.id, error: `not delivered by WhatsApp: ${reason}`.slice(0, 1000) } });
  }
}
return out;
